from concurrent.futures import ThreadPoolExecutor
import time

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity (0 or 1) of each element of xs, in input order.

    The work is done in parallel on a thread pool. The result order
    matches the input order and does not depend on the worker count or
    on the order in which tasks finish.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([0, 1, 2, 3, 4, 5]) == [0, 1, 0, 1, 0, 1]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative_numbers() -> None:
    assert parities([-1, -2, -3, -4]) == [1, 0, 1, 0]


def test_parities_preserves_order_and_duplicates() -> None:
    xs = [7, 7, 2, 2, 9, 0, 7]
    assert parities(xs) == [1, 1, 0, 0, 1, 0, 1]


def test_parities_large_input_matches_sequential() -> None:
    xs = list(range(-500, 1500))
    assert parities(xs) == [parity(x) for x in xs]


def test_parities_does_not_mutate_input() -> None:
    xs = [3, 4, 5]
    parities(xs)
    assert xs == [3, 4, 5]


def test_parities_order_independent_of_completion_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # Early elements finish last; the result must still be in input order.
    def slow_parity(x: int) -> int:
        time.sleep(0.02 if x < 4 else 0.0)
        return x % 2

    monkeypatch.setattr(f"{__name__}.parity", slow_parity)
    xs = list(range(16))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_returns_ints_zero_or_one() -> None:
    result = parities([10, 11, -7, 0])
    assert all(type(p) is int and p in (0, 1) for p in result)


def test_parities_propagates_worker_exception(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    def bad_parity(x: int) -> int:
        if x == 3:
            raise ValueError("boom")
        return x % 2

    monkeypatch.setattr(f"{__name__}.parity", bad_parity)
    with pytest.raises(ValueError):
        parities([1, 2, 3, 4])
